import{_ as n,C as e,o as s,c as d,E as a,a7 as c}from"./chunks/framework.FWlv_suP.js";const v=JSON.parse('{"title":"Qurio Privacy Policy","description":"Privacy Policy for Qurio, presented within Policy Hub.","frontmatter":{"title":"Qurio Privacy Policy","description":"Privacy Policy for Qurio, presented within Policy Hub."},"headers":[],"relativePath":"apps/qurio/privacy.md","filePath":"apps/qurio/privacy.md"}'),l={name:"apps/qurio/privacy.md"};function p(u,r,h,m,g,f){const i=e("AppBreadcrumbs"),o=e("AppSubnav"),t=e("CopyStandaloneUrl");return s(),d("div",null,[a(i,{"app-id":"qurio",current:"Privacy Policy"}),a(o,{"app-id":"qurio"}),a(t,{path:"/privacy/qurio",label:"Copy standalone privacy URL","copied-label":"Privacy Policy URL copied","document-name":"Qurio privacy policy"}),r[0]||(r[0]=c('<h1 id="privacy-policy-for-qurio" tabindex="-1">Privacy Policy for Qurio <a class="header-anchor" href="#privacy-policy-for-qurio" aria-label="Permalink to &quot;Privacy Policy for Qurio&quot;">​</a></h1><p><strong>Effective Date:</strong> September 8, 2026<br><strong>Last Updated:</strong> September 22, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Qurio is a multilingual learning and exam-preparation app developed by <strong>Anand Raja</strong>. It provides study material, quizzes, progress tracking, practice history, and exam plans through authenticated accounts.</p><p>Qurio has no advertising, does not sell personal information, and does not use developer-operated analytics or tracking SDKs.</p><h2 id="account-information" tabindex="-1">Account information <a class="header-anchor" href="#account-information" aria-label="Permalink to &quot;Account information&quot;">​</a></h2><p>Registration processes your display name, email address, and password through Supabase Authentication. The developer cannot view your plaintext password. Qurio also processes email-verification and password-reset requests, account status and role, approval decisions, reasons, and timestamps.</p><p>Verified users may be approved automatically when the owner enables that setting, or reviewed by an owner or administrator.</p><h2 id="learning-information" tabindex="-1">Learning information <a class="header-anchor" href="#learning-information" aria-label="Permalink to &quot;Learning information&quot;">​</a></h2><p>Qurio stores account-linked learning information including:</p><ul><li>Language, theme, curriculum, grade, and selected exam plan</li><li>Study-content identifiers, reading progress, completion state, and timestamps</li><li>Quiz identifiers, selected and correct answers, hint use, time spent, scores, pass results, and attempt timestamps</li><li>Exam-plan dates, task identifiers and types, and completion status</li></ul><p>For approved accounts, this is the canonical record in Qurio&#39;s hosted Supabase PostgreSQL (SQL) database. Database Row Level Security restricts learners to their own learner-state records.</p><h2 id="administration-and-audit-records" tabindex="-1">Administration and audit records <a class="header-anchor" href="#administration-and-audit-records" aria-label="Permalink to &quot;Administration and audit records&quot;">​</a></h2><p>Authorized owners and administrators can manage verification, approval, account status, and roles. Security audit records may contain the affected account&#39;s name and email; the acting administrator&#39;s account, role, and action; old and new status or role; a reason; and a timestamp.</p><h2 id="device-and-browser-storage" tabindex="-1">Device and browser storage <a class="header-anchor" href="#device-and-browser-storage" aria-label="Permalink to &quot;Device and browser storage&quot;">​</a></h2><p>Qurio keeps limited information on the device or browser so the app can operate: the authenticated session, display preferences, temporary synchronization cache, notification-permission state, and reminder schedule. The device cache is not the canonical account record; approved users&#39; preferences, learning progress, quiz attempts and answers, bookmarks, and exam-plan progress are stored in the Supabase SQL database.</p><p>Optional web app locking stores a salted, password-derived PIN verifier in IndexedDB. The web app does not store the PIN in plaintext. Optional Android biometric unlock stores only random unlock material protected by Android Keystore; it does not store the PIN. Android performs biometric matching; Qurio never receives fingerprint or face templates.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>If you enable Android practice reminders, Qurio asks for notification permission, saves your selected days and time to your account settings in the Supabase SQL database, and schedules local notifications on the device. Boot-completed, time-change, and timezone-change events restore enabled schedules after restarts or clock changes.</p><p>No push token is uploaded. Reminders contain no quiz answers, scores, or sensitive learning details. You can disable reminders in Qurio and revoke permission in Android settings.</p><h2 id="service-providers" tabindex="-1">Service providers <a class="header-anchor" href="#service-providers" aria-label="Permalink to &quot;Service providers&quot;">​</a></h2><p>Qurio uses <strong>Supabase</strong>, including Supabase Authentication and its hosted PostgreSQL (SQL) database, for authentication, profiles, authorization, learner state, settings, and audit records; a configured authentication email provider for verification and reset emails; <strong>GitHub Pages</strong> for the web client; and <strong>GitHub raw-content delivery</strong> for learning files. These services process necessary data and ordinary connection metadata such as IP address, user agent, request time, and requested resource under their own policies.</p><h2 id="android-permissions" tabindex="-1">Android permissions <a class="header-anchor" href="#android-permissions" aria-label="Permalink to &quot;Android permissions&quot;">​</a></h2><p>Qurio uses:</p><ul><li><strong>Internet access</strong> for authentication, synchronization, and learning content</li><li><strong>Notifications</strong> for optional practice reminders</li><li><strong>Receive boot completed</strong> to restore enabled reminders</li><li><strong>Biometric authentication</strong> only when you enable biometric unlock</li></ul><p>Qurio does not request location, contacts, phone, SMS, call logs, camera, microphone, or broad storage access.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and deletion&quot;">​</a></h2><p>Account and learning records in the Supabase SQL database remain while needed to provide Qurio. Signing out ends the local session but does not delete server data. Device and browser information remains until cleared through the browser or Android settings.</p><p>You can permanently delete your own Learner or Administrator account in <strong>Settings</strong> by confirming the current account email. The authenticated deletion removes the Auth account and linked profile, settings, learner-state records, quiz attempts and answers, bookmarks, and exam-plan progress. It also clears the deleted account&#39;s active local session and app-lock data on the installation that submits the deletion. Owner self-deletion is blocked until ownership is transferred.</p><p>Minimal audit records and support correspondence may remain where necessary for security, disputes, legal duties, or accountability. See the Data Deletion page.</p><h2 id="children-and-families" tabindex="-1">Children and families <a class="header-anchor" href="#children-and-families" aria-label="Permalink to &quot;Children and families&quot;">​</a></h2><p>Qurio may be used by school-age learners. A parent, guardian, school, or authorized adult should supervise account creation where consent is required. Children should not send unnecessary personal information to support. A parent or guardian may request access to or deletion of a child&#39;s account. Qurio does not serve behaviorally targeted advertising or build advertising profiles.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><p>Qurio uses HTTPS, Supabase Authentication, email verification, role-based authorization, Row Level Security, approval controls, and optional device locking. Protect your email account, password, device, PIN, and active session.</p><h2 id="changes-and-contact" tabindex="-1">Changes and contact <a class="header-anchor" href="#changes-and-contact" aria-label="Permalink to &quot;Changes and contact&quot;">​</a></h2><p>This policy may change with Qurio&#39;s features or providers. Updated dates will be published here.</p><ul><li><strong>Developer:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',37))])}const y=n(l,[["render",p]]);export{v as __pageData,y as default};
